import csv
with open('csv/Laboratory.csv') as f:
    rows = list(csv.DictReader(f))
# Get all patient IDs and their lab values
patients = {}
for r in rows:
    pid = r['ID']
    if r['WBC'] and r['WBC']!='':
        if pid not in patients: patients[pid]={'WBC':[],'FG':[]}
        patients[pid]['WBC'].append(float(r['WBC']))
    if r['FG'] and r['FG']!='' and r['FG']!='-':
        if pid not in patients: patients[pid]={'WBC':[],'FG':[]}
        patients[pid]['FG'].append(float(r['FG']))
# Get sex info
with open('patient_sex.csv') as f:
    sex = list(csv.DictReader(f))
sex_map = {s['ID']:s['SEX'] for s in sex}
# Find WBC values that seem like outliers (values < 4 or > 10)
wbc_outliers = 0
wbc_normal = 0
for pid,pdata in patients.items():
    if pdata['WBC']:
        avg_wbc = sum(pdata['WBC'])/len(pdata['WBC'])
        if avg_wbc < 4 or avg_wbc > 10:
            wbc_outliers += 1
        else:
            wbc_normal += 1
print('Patients with WBC normal (4-10):', wbc_normal)
print('Patients with WBC abnormal (<4 or >10):', wbc_outliers)
print('Male patients:', sum(1 for s in sex.values() if s=='M'))

